<script setup>
import { computed, ref } from 'vue';
import { attributionLabels, attributionTypes, categoryLabels, evidenceLabels, evidenceRequirements, expenseLabels, expenseTypes, inputModes, modeLabels, templateCategories } from '../views/approvalTemplateModel.js';
const props = defineProps({ form: { type: Object, required: true }, roles: { type: Array, required: true }, users: { type: Array, required: true }, creating: { type: Boolean, default: false }, busy: { type: Boolean, default: false }, submitLabel: { type: String, required: true } });
const emit = defineEmits(['submit', 'cancel']);
const step = ref(0);
const steps = computed(() => ['基本信息', '发起角色', '申请依据', ...(props.form.category === 'EXPENSE' ? ['费用配置'] : []), '审批节点', '确认']);
const section = computed(() => steps.value[step.value]);
function changeCategory() { if (props.form.category === 'TIRE') props.form.templateCode = 'TIRE_REQUEST'; else if (props.form.templateCode === 'TIRE_REQUEST') props.form.templateCode = ''; step.value = Math.min(step.value, steps.value.length - 1); }
function addNode() { props.form.nodes.push({ nodeOrder: props.form.nodes.length + 1, nodeName: '', positionId: '', approverUserId: '', allowReturn: true }); }
function removeNode(index) { if (props.form.nodes.length < 2) return; props.form.nodes.splice(index, 1); props.form.nodes.forEach((node, i) => { node.nodeOrder = i + 1; }); }
function next() { step.value = Math.min(step.value + 1, steps.value.length - 1); }
</script>

<template>
  <div class="ui-template-wizard"><nav class="ui-step-line" aria-label="模板配置步骤"><strong v-for="(name,index) in steps" :key="name" :class="{active:step===index}">{{ index+1 }} {{ name }}</strong></nav>
    <form @submit.prevent="section === '确认' ? emit('submit') : next()">
      <div v-if="section === '基本信息'" class="ui-form-grid"><template v-if="creating"><label class="ui-form-field">模板类别<select v-model="form.category" @change="changeCategory"><option v-for="value in templateCategories" :key="value" :value="value">{{ categoryLabels[value] }}</option></select></label><label class="ui-form-field">模板代码<input v-model.trim="form.templateCode" required :readonly="form.category==='TIRE'" placeholder="例如 EXPENSE_WATER" /></label></template><label class="ui-form-field">流程名称<input v-model.trim="form.flowName" required placeholder="供业务人员识别的名称" /></label><p class="muted">模板代码创建后保持稳定；版本更新不会覆盖旧审批历史。</p></div>
      <div v-else-if="section === '发起角色'"><h3>谁可以发起</h3><p v-if="form.category === 'TIRE'" class="muted">换胎使用专用入口，最终资格仍由 tire:request 和业务 Policy 决定。</p><div class="ui-option-grid"><label v-for="role in roles" :key="role.id"><input v-model="form.initiatorRoleIds" type="checkbox" :value="role.id" /> {{ role.roleName }}</label></div><p v-if="!roles.length" class="error">尚未读取角色，请返回列表刷新后重试。</p></div>
      <div v-else-if="section === '申请依据'"><label class="ui-form-field">申请图片依据<select v-model="form.evidenceRequirement"><option v-for="value in evidenceRequirements" :key="value" :value="value">{{ evidenceLabels[value] }}</option></select></label><p class="muted">审批申请的每个 Submission 版本独立保存依据；旧版本不被新版本覆盖。</p></div>
      <div v-else-if="section === '费用配置'"><label class="ui-form-field">费用类型<select v-model="form.expenseType" required><option value="">请选择费用类型</option><option v-for="value in expenseTypes" :key="value" :value="value">{{ expenseLabels[value] || value }}</option></select></label><div class="ui-option-grid"><fieldset><legend>允许的录入方式</legend><label v-for="value in inputModes" :key="value"><input v-model="form.inputModes" type="checkbox" :value="value" /> {{ modeLabels[value] }}</label></fieldset><fieldset><legend>允许的费用归属</legend><label v-for="value in attributionTypes" :key="value"><input v-model="form.attributionTypes" type="checkbox" :value="value" /> {{ attributionLabels[value] }}</label></fieldset></div><p class="muted">Excel 解析在发起审批时仅于浏览器本地进行。</p></div>
      <div v-else-if="section === '审批节点'"><h3>审批节点</h3><div v-for="(node,index) in form.nodes" :key="index" class="ui-section-card ui-wizard-node"><div class="ui-list-heading"><h4>第 {{ index+1 }} 节点</h4><button type="button" :disabled="form.nodes.length===1" @click="removeNode(index)">移除</button></div><div class="ui-form-grid"><label class="ui-form-field">节点名称<input v-model.trim="node.nodeName" required /></label><label class="ui-form-field">审批人<select v-model.number="node.approverUserId" required><option value="">请选择用户</option><option v-if="node.approverUserId && !users.some(user => user.id === Number(node.approverUserId))" :value="Number(node.approverUserId)">原审批人（账号已停用）</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.phone }} · {{ user.roleName || user.roleCode }}</option></select></label><label class="ui-form-field">岗位编号（可选）<input v-model="node.positionId" type="number" min="1" placeholder="当前接口要求编号" /></label><label><input v-model="node.allowReturn" type="checkbox" /> 允许打回</label></div></div><button type="button" @click="addNode">＋ 增加节点</button></div>
      <div v-else><h3>确认配置</h3><dl class="ui-detail-grid"><dt>模板类别</dt><dd>{{ categoryLabels[form.category] }}</dd><dt>流程名称</dt><dd>{{ form.flowName }}</dd><dt>发起角色</dt><dd>{{ roles.filter(role => form.initiatorRoleIds.includes(role.id)).map(role => role.roleName).join('、') || '未选择' }}</dd><dt>申请依据</dt><dd>{{ evidenceLabels[form.evidenceRequirement] }}</dd><template v-if="form.category==='EXPENSE'"><dt>费用类型</dt><dd>{{ expenseLabels[form.expenseType] || '未选择' }}</dd><dt>录入方式</dt><dd>{{ form.inputModes.map(value => modeLabels[value]).join('、') }}</dd><dt>费用归属</dt><dd>{{ form.attributionTypes.map(value => attributionLabels[value]).join('、') }}</dd></template><dt>审批节点</dt><dd>{{ form.nodes.map(node => node.nodeName || '未命名').join(' → ') }}</dd></dl><p class="muted">保存草稿与发布是不同操作；请核对审批人及费用配置。</p></div>
      <div class="ui-dialog-actions"><button type="button" @click="emit('cancel')">取消</button><button v-if="step>0" type="button" @click="step--">上一步</button><button class="primary" :disabled="busy || (section==='发起角色' && !roles.length)">{{ section==='确认' ? submitLabel : '下一步' }}</button></div>
    </form>
  </div>
</template>
